import { Button } from '@refy-design/web';
import { Hero } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof Hero>,
    'title' | 'accent' | 'lead' | 'actions'
  > = {
    title: 'Your design, your way',
    accent: '.',
    lead: 'Build extensible UIs with native AI.',
    actions: (
      <>
        <Button variant="primary" size="lg">
          Open in Playground →
        </Button>
        <Button size="lg" href="#docs">
          Read the docs
        </Button>
      </>
    ),
  };
  return <Hero {...args} />;
}

